stion','Mostrar pregunta')); ?>"><?php echo s($phlegmtext('Show answer','Mostrar respuesta')); ?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--next" type="button" data-yang-next><?php echo s($phlegmtext('Next','Siguiente')); ?> →</button></div><p class="single-herbs-guide__yang-progress" data-yang-progress><?php echo s($phlegmtext('Card','Tarjeta')); ?> 1 <?php echo s($phlegmtext('of','de')); ?> <?php echo count($phlegmquestions); ?></p></div></section>
